from datetime import datetime, timezone
from decimal import Decimal
from ledgerly import audit
from ledgerly.models import Payment
from ledgerly.support import process_refund_request
from ledgerly.errors import BillingError

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(amt="100.00", status="captured"):
    return Payment("pay_1","inv_1",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# rounding
p=mk(); process_refund_request(p,"49.995","u",T0); print("round", p.refunded_amount)
# full refund status
p=mk(); process_refund_request(p,"100.00","u",T0); print("full", p.refunded_amount, p.status)
# over refund
p=mk(); 
try: process_refund_request(p,"100.01","u",T0)
except BillingError as e: print("over", e.code)
# non captured
p=mk(status="authorized")
try: process_refund_request(p,"1.00","u",T0)
except BillingError as e: print("state", e.code)
# approval
p=mk("1000.00")
try: process_refund_request(p,"500.01","u",T0)
except BillingError as e: print("approval", e.code)
p=mk("1000.00"); process_refund_request(p,"500.01","u",T0,approved_by="boss"); print("approved", p.refunded_amount)
# idempotency
audit.clear()
p=mk()
r1=process_refund_request(p,"40.00","u",T0,idempotency_key="k1")
r2=process_refund_request(p,"40.00","u",T0,idempotency_key="k1")
print("idem", p.refunded_amount, r1 is r2, len(audit.events()), audit.events()[0].get("idempotency_key"))
# idempotency checked before state validation
p=mk(status="authorized")
try: process_refund_request(p,"1.00","u",T0,idempotency_key="k1")
except BillingError as e: print("unexpected", e)
else: print("idem-before-state ok")
EOF"}

